--
-- Table structure for table `metrics`
--

DROP TABLE IF EXISTS `metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `metrics` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `resource_id` bigint NOT NULL,
  `metric_name` varchar(100) NOT NULL,
  `metric_value` double NOT NULL,
  `metric_timestamp` datetime NOT NULL,
  PRIMARY KEY (`id`,`metric_timestamp`),
  UNIQUE KEY `uniq_metrics_resource_metric` (`resource_id`,`metric_name`),
  KEY `idx_lookup` (`resource_id`,`metric_name`,`metric_timestamp`)
) ENGINE=InnoDB AUTO_INCREMENT=45251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

